//! `AgentApiKey`: the key another platform presents to reach one agent (design §3.6).
//!
//! Old: `src/features/agent-api-keys/{repository,service}.ts`. The key is generated by the
//! caller and only its hash is stored: the route looks a presented key up by
//! `hex(SHA-256(key))` (`agents_auth::api_key::hash_agent_api_key`), which is the byte-for-byte
//! value the TypeScript backfill wrote, so rows written before this port still resolve.
//!
//! The plaintext `key` column stays: Prisma declares it `String @unique` and not null, and this
//! crate never migrates. It holds the *masked* key (`rantai_sk_ab…wxyz`), which is exactly what
//! the dashboard shows and what it showed before this port — never the secret (differences.md
//! row 141). The old plaintext lookup (`findAgentApiKeyByKey`) is not ported: a row whose
//! `keyHash` is still null does not authenticate until the SQL backfill has run.
//!
//! Every write leaves an `AuditLog` row in its own transaction (§3.7), and every read and write
//! of a key management route is scoped by the organisation: another tenant's key is
//! [`StoreError::NotFound`].

use chrono::NaiveDateTime;
use serde_json::json;
use sqlx::{PgPool, Postgres, Transaction};

use crate::audit::{self, Actor};
use crate::{StoreError, StoreResult, new_id, now};

#[derive(Debug, Clone, PartialEq, Eq, sqlx::FromRow)]
#[sqlx(rename_all = "camelCase")]
pub struct ApiKeyRow {
    pub id: String,
    pub name: String,
    /// The legacy plaintext column. Rows written here hold the hash (see the module docs).
    pub key: String,
    pub key_hash: Option<String>,
    /// The agent the key acts as.
    pub assistant_id: String,
    /// `chat`, `chat:stream`. An empty list allows everything, as the old check did.
    pub scopes: Vec<String>,
    /// An empty list allows every address.
    pub ip_whitelist: Vec<String>,
    pub request_count: i32,
    pub last_used_at: Option<NaiveDateTime>,
    pub organization_id: Option<String>,
    pub created_by: Option<String>,
    pub enabled: bool,
    pub expires_at: Option<NaiveDateTime>,
    pub created_at: NaiveDateTime,
    pub updated_at: NaiveDateTime,
}

const COLUMNS: &str = r#""id","name","key","keyHash","assistantId","scopes","ipWhitelist","requestCount","lastUsedAt","organizationId","createdBy","enabled","expiresAt","createdAt","updatedAt""#;

/// A key the route has already generated and hashed.
#[derive(Debug, Clone)]
pub struct NewKey<'a> {
    pub name: &'a str,
    /// The agent the key acts as; it must be one of the organisation's own.
    pub assistant_id: &'a str,
    /// `hex(SHA-256(key))`; the plaintext never reaches this crate.
    pub key_hash: &'a str,
    /// The masked key the dashboard shows: `rantai_sk_` and the first and last characters. The
    /// secret is never stored, and masking this value again returns it unchanged.
    pub key_hint: &'a str,
    pub scopes: Vec<String>,
    pub ip_whitelist: Vec<String>,
    pub expires_at: Option<NaiveDateTime>,
    pub created_by: &'a str,
}

/// What an update may change. `None` leaves the field as it is; `Some(None)` on the expiry
/// clears it.
#[derive(Debug, Clone, Default)]
pub struct KeyPatch {
    pub name: Option<String>,
    pub scopes: Option<Vec<String>>,
    pub ip_whitelist: Option<Vec<String>>,
    pub enabled: Option<bool>,
    pub expires_at: Option<Option<NaiveDateTime>>,
}

/// The keys of one agent, or of the whole organisation when `assistant_id` is none.
pub async fn list(
    db: &PgPool,
    org_id: &str,
    assistant_id: Option<&str>,
) -> StoreResult<Vec<ApiKeyRow>> {
    let sql = format!(
        r#"SELECT {COLUMNS} FROM "AgentApiKey"
           WHERE "organizationId" = $1 AND ($2::text IS NULL OR "assistantId" = $2)
           ORDER BY "createdAt" DESC, "id" DESC"#
    );
    Ok(sqlx::query_as::<_, ApiKeyRow>(&sql)
        .bind(org_id)
        .bind(assistant_id)
        .fetch_all(db)
        .await?)
}

/// One key of the organisation. Another organisation's key is `NotFound`.
pub async fn get(db: &PgPool, org_id: &str, id: &str) -> StoreResult<ApiKeyRow> {
    let sql =
        format!(r#"SELECT {COLUMNS} FROM "AgentApiKey" WHERE "id" = $1 AND "organizationId" = $2"#);
    sqlx::query_as::<_, ApiKeyRow>(&sql)
        .bind(id)
        .bind(org_id)
        .fetch_optional(db)
        .await?
        .ok_or(StoreError::NotFound)
}

/// Writes a key and its audit row in one transaction.
///
/// An agent that is not one of the organisation's own — another tenant's, a built-in, or an id
/// that does not exist — is `NotFound`, so a key can never be minted for an agent the caller
/// could not otherwise reach.
pub async fn create(
    db: &PgPool,
    org_id: &str,
    new: &NewKey<'_>,
    actor: &Actor<'_>,
) -> StoreResult<ApiKeyRow> {
    let mut tx = db.begin().await?;
    let agent_here = sqlx::query_scalar::<_, bool>(
        r#"SELECT EXISTS (SELECT 1 FROM "Assistant"
             WHERE "id" = $1 AND "organizationId" = $2 AND "isBuiltIn" = false)"#,
    )
    .bind(new.assistant_id)
    .bind(org_id)
    .fetch_one(&mut *tx)
    .await?;
    if !agent_here {
        return Err(StoreError::NotFound);
    }
    let ts = now();
    let sql = format!(
        r#"INSERT INTO "AgentApiKey"
             ("id","name","key","keyHash","assistantId","scopes","ipWhitelist","requestCount",
              "organizationId","createdBy","enabled","expiresAt","createdAt","updatedAt")
           VALUES ($1,$2,$3,$4,$5,$6,$7,0,$8,$9,true,$10,$11,$11)
           RETURNING {COLUMNS}"#
    );
    let row = sqlx::query_as::<_, ApiKeyRow>(&sql)
        .bind(new_id())
        .bind(new.name)
        .bind(new.key_hint)
        .bind(new.key_hash)
        .bind(new.assistant_id)
        .bind(&new.scopes)
        .bind(&new.ip_whitelist)
        .bind(org_id)
        .bind(new.created_by)
        .bind(new.expires_at)
        .bind(ts)
        .fetch_one(&mut *tx)
        .await?;
    audit::record(
        &mut tx,
        org_id,
        actor,
        "api_key.create",
        format!("api_key:{}", row.id),
        detail_of(&row),
    )
    .await?;
    tx.commit().await?;
    Ok(row)
}

/// Changes a key and writes the audit row in the same transaction. Another organisation's key,
/// or an unknown id, is `NotFound`.
pub async fn update(
    db: &PgPool,
    org_id: &str,
    id: &str,
    patch: &KeyPatch,
    actor: &Actor<'_>,
) -> StoreResult<ApiKeyRow> {
    let mut tx = db.begin().await?;
    let current = lock(&mut tx, org_id, id).await?;
    let ts = now();
    let sql = format!(
        r#"UPDATE "AgentApiKey"
             SET "name" = $2, "scopes" = $3, "ipWhitelist" = $4, "enabled" = $5,
                 "expiresAt" = $6, "updatedAt" = $7
           WHERE "id" = $1 AND "organizationId" = $8
           RETURNING {COLUMNS}"#
    );
    let row = sqlx::query_as::<_, ApiKeyRow>(&sql)
        .bind(id)
        .bind(patch.name.clone().unwrap_or(current.name))
        .bind(patch.scopes.clone().unwrap_or(current.scopes))
        .bind(patch.ip_whitelist.clone().unwrap_or(current.ip_whitelist))
        .bind(patch.enabled.unwrap_or(current.enabled))
        .bind(match patch.expires_at {
            Some(value) => value,
            None => current.expires_at,
        })
        .bind(ts)
        .bind(org_id)
        .fetch_one(&mut *tx)
        .await?;
    audit::record(
        &mut tx,
        org_id,
        actor,
        "api_key.update",
        format!("api_key:{}", row.id),
        detail_of(&row),
    )
    .await?;
    tx.commit().await?;
    Ok(row)
}

/// Deletes a key and writes the audit row in the same transaction.
pub async fn delete(db: &PgPool, org_id: &str, id: &str, actor: &Actor<'_>) -> StoreResult<()> {
    let mut tx = db.begin().await?;
    let current = lock(&mut tx, org_id, id).await?;
    sqlx::query(r#"DELETE FROM "AgentApiKey" WHERE "id" = $1 AND "organizationId" = $2"#)
        .bind(id)
        .bind(org_id)
        .execute(&mut *tx)
        .await?;
    audit::record(
        &mut tx,
        org_id,
        actor,
        "api_key.delete",
        format!("api_key:{id}"),
        detail_of(&current),
    )
    .await?;
    tx.commit().await?;
    Ok(())
}

/// The key a presented value hashes to, whatever its organisation: this is the authentication
/// lookup, and the route makes the tenant decision from the row it finds.
pub async fn find_by_hash(db: &PgPool, key_hash: &str) -> StoreResult<Option<ApiKeyRow>> {
    let sql = format!(r#"SELECT {COLUMNS} FROM "AgentApiKey" WHERE "keyHash" = $1"#);
    Ok(sqlx::query_as::<_, ApiKeyRow>(&sql)
        .bind(key_hash)
        .fetch_optional(db)
        .await?)
}

/// Counts one use. One statement, so two concurrent requests never lose an increment
/// (`requestCount = requestCount + 1` is read and written under the row lock Postgres takes for
/// the update).
pub async fn record_use(db: &PgPool, id: &str, at: NaiveDateTime) -> StoreResult<()> {
    sqlx::query(
        r#"UPDATE "AgentApiKey"
             SET "requestCount" = "requestCount" + 1, "lastUsedAt" = $2
           WHERE "id" = $1"#,
    )
    .bind(id)
    .bind(at)
    .execute(db)
    .await?;
    Ok(())
}

/// The row as the update and the delete read it, locked: two writers on one key queue behind
/// each other, and the second one sees the first one's change.
async fn lock(
    tx: &mut Transaction<'_, Postgres>,
    org_id: &str,
    id: &str,
) -> StoreResult<ApiKeyRow> {
    let sql = format!(
        r#"SELECT {COLUMNS} FROM "AgentApiKey"
           WHERE "id" = $1 AND "organizationId" = $2
           FOR UPDATE"#
    );
    sqlx::query_as::<_, ApiKeyRow>(&sql)
        .bind(id)
        .bind(org_id)
        .fetch_optional(&mut **tx)
        .await?
        .ok_or(StoreError::NotFound)
}

/// What the audit row records about a key: what it is, never the secret.
fn detail_of(row: &ApiKeyRow) -> serde_json::Value {
    json!({
        "name": row.name,
        "assistantId": row.assistant_id,
        "scopes": row.scopes,
        "ipWhitelist": row.ip_whitelist,
        "enabled": row.enabled,
    })
}
